    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            const w = window.innerWidth;
            const h = window.innerHeight;
            mouseRef.current = { 
                x: (e.clientX - w / 2) / (w / 2), 
                y: (e.clientY - h / 2) / (h / 2) 
