import React, { useEffect, useRef } from 'react';

export const ResourcesHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.parentElement?.clientWidth || 800;
        let h = canvas.parentElement?.clientHeight || 600;
        canvas.width = w;
        canvas.height = h;

        let frame = 0;
        let animationFrameId: number;

        // State for dynamic events
        const extractions: { x: number, y: number, life: number, code: string, color: string }[] = [];
        const NODE_COLORS = ['#f59e0b', '#06b6d4', '#d946ef', '#ef4444', '#10b981', '#f43f5e'];

        const render = () => {
            frame++;
            const time = frame * 0.008; 
            const scroll = frame * 2.0;

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            // 2. Draw "Strata" Lines (Optimized)
            const lines = 35; // Reduced from 55
            const step = h / lines;
            const scanX = (w/2) + Math.sin(time * 0.5) * (w * 0.4);

            for (let i = 0; i < lines; i++) {
                const normI = i / lines;
                const perspectiveY = h * (0.2 + Math.pow(normI, 1.2) * 0.8);

                ctx.beginPath();

                const alpha = normI * 0.6 + 0.1;
                const hue = 160 + (1-normI) * 60; 

                // Optimized Step: 8px instead of 3px
                for (let x = 0; x <= w; x += 8) {
                    const worldX = x + scroll;
                    const worldZ = i * 50; 

                    // Simplified Terrain Math
                    let elevation = Math.sin(worldX * 0.002 + worldZ * 0.001) * 40;

                    // Reduced complexity ridges
                    const ridge1 = Math.pow(1 - Math.abs(Math.sin(worldX * 0.006 + time * 0.2)), 3);
                    elevation -= ridge1 * 50; 

                    // Scanner Interaction
                    const distToScan = Math.abs(x - scanX);
                    if (distToScan < 120) {
                        const scanInfluence = 1 - distToScan / 120;
                        elevation += Math.sin(x * 0.2) * 5 * scanInfluence;
                    }

                    const finalY = perspectiveY + elevation;

                    if (x === 0) ctx.moveTo(x, finalY);
                    else ctx.lineTo(x, finalY);
                }

                // Simplified Gradient Logic
                ctx.strokeStyle = `hsla(${hue}, 50%, 40%, ${alpha * 0.3})`;
                ctx.lineWidth = 1 + normI;

                // Only create gradient if near scan line
                if (scanX > -150 && scanX < w + 150) {
                    const grad = ctx.createLinearGradient(scanX - 100, 0, scanX + 100, 0);
                    grad.addColorStop(0, `hsla(${hue}, 50%, 40%, ${alpha * 0.3})`);
                    grad.addColorStop(0.5, `hsla(${hue - 40}, 90%, 80%, ${alpha})`);
                    grad.addColorStop(1, `hsla(${hue}, 50%, 40%, ${alpha * 0.3})`);
                    ctx.strokeStyle = grad;
                }

                ctx.stroke();
            }

            // 3. Draw Resources & Extraction (Simplified)
            const dotCount = 6; // Reduced from 8
            for(let j=0; j<dotCount; j++) {
                const nodeColor = NODE_COLORS[j % NODE_COLORS.length];
                const virtualX = (j * (w / dotCount) + scroll * 0.5) % (w + 200) - 100;

                if (virtualX < -50 || virtualX > w + 50) continue;

                const perspectiveY = h * (0.2 + Math.pow(0.7, 1.2) * 0.8);
                const dy = perspectiveY + Math.sin(virtualX * 0.002) * 40; // Approx Y

                const distToScan = Math.abs(virtualX - scanX);

                // Trigger Extraction
                if (distToScan < 30 && Math.random() > 0.99) { // Lower prob
                    const tooClose = extractions.some(e => Math.abs(e.x - virtualX) < 40);
                    if (!tooClose) {
                        extractions.push({ 
                            x: virtualX, y: dy, life: 1.0, 
                            code: "RES-" + Math.floor(Math.random() * 99),
                            color: nodeColor
                        });
                    }
                }

                if (distToScan < 100) {
                    ctx.fillStyle = '#fff';
                    ctx.shadowColor = nodeColor;
                    ctx.shadowBlur = 10; // Lower blur
                    ctx.beginPath(); ctx.arc(virtualX, dy, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                }
            }

            // 4. Render Active Extractions
            for (let i = extractions.length - 1; i >= 0; i--) {
                const ex = extractions[i];
                ex.life -= 0.02;
                ex.x -= 1.0; 

                if (ex.life <= 0) {
                    extractions.splice(i, 1);
                    continue;
                }

                const beamHeight = 150 * (1 - ex.life);
                ctx.fillStyle = ex.color;
                ctx.globalAlpha = Math.sin(ex.life * Math.PI) * 0.6;
                ctx.fillRect(ex.x - 1, ex.y - beamHeight, 2, beamHeight);
                ctx.globalAlpha = 1;
            }

            animationFrameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.parentElement.clientWidth;
                h = canvas.parentElement.clientHeight;
                canvas.width = w;
                canvas.height = h;
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

import React, { useEffect, useRef } from 'react';

export const SmallBusinessHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = canvas.parentElement?.clientWidth || 800;
        let h = canvas.height = canvas.parentElement?.clientHeight || 600;
        let frameId: number;
        let time = 0;

        // --- 3D PARTICLE ENGINE ---
        const PARTICLE_COUNT = 400; // Reduced from 800
        const CAM_Z = 800;
        const CX = w * 0.5;
        const CY = h * 0.5;

        interface Point3D { x: number; y: number; z: number }
        interface Particle {
            current: Point3D;
            target: Point3D;
            color: string;
            size: number;
        }

        const particles: Particle[] = [];
        let phase = 0; // 0: CLOUD, 1: SPHERE, 2: CUBE
        let phaseTimer = 0;
        const PHASE_DURATION = 400; 

        // --- GENERATORS ---
        const getCloudPoint = (): Point3D => {
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.random() * Math.PI * 2;
            const rMain = 250 + Math.random() * 50;
            const rTube = 80 + Math.random() * 40;
            return {
                x: (rMain + rTube * Math.cos(phi)) * Math.cos(theta),
                y: (rMain + rTube * Math.cos(phi)) * Math.sin(theta),
                z: rTube * Math.sin(phi)
            };
        };

        const getSpherePoint = (i: number, total: number, radius: number): Point3D => {
            const phi = Math.acos(-1 + (2 * i) / total);
            const theta = Math.sqrt(total * Math.PI) * phi;
            return {
                x: radius * Math.cos(theta) * Math.sin(phi),
                y: radius * Math.sin(theta) * Math.sin(phi),
                z: radius * Math.cos(phi)
            };
        };

        const getCubePoint = (i: number, total: number): Point3D => {
            const dim = Math.floor(Math.cbrt(total));
            const idx = i % (dim*dim*dim); 
            const x = (idx % dim);
            const y = Math.floor((idx / dim) % dim);
            const z = Math.floor(idx / (dim * dim));
            const spacing = 45; // Adjusted for lower count
            const offset = (dim * spacing) / 2;
            return {
                x: x * spacing - offset,
                y: y * spacing - offset,
                z: z * spacing - offset
            };
        };

        // --- INIT ---
        for (let i = 0; i < PARTICLE_COUNT; i++) {
            const colors = ['#8b5cf6', '#a78bfa', '#22d3ee', '#c4b5fd'];
            particles.push({
                current: getCloudPoint(),
                target: getCloudPoint(),
                color: colors[Math.floor(Math.random() * colors.length)],
                size: Math.random() > 0.9 ? 2.5 : 1.2
            });
        }

        const setTargetShape = (shape: number) => {
            particles.forEach((p, i) => {
                if (shape === 0) p.target = getCloudPoint();
                else if (shape === 1) p.target = getSpherePoint(i, PARTICLE_COUNT, 220);
                else if (shape === 2) p.target = getCubePoint(i, PARTICLE_COUNT);
            });
        };

        // Reusable array for sorting
        const sortedParticles = new Array(PARTICLE_COUNT);

        const render = () => {
            time += 0.008;
            phaseTimer++;

            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                setTargetShape(phase);
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const rotX = time * 0.3 + (mouseRef.current.y * 0.1);
            const rotY = time * 0.4 + (mouseRef.current.x * 0.1);

            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);

            // Update & Project
            let validCount = 0;

            for(let i=0; i<PARTICLE_COUNT; i++) {
                const p = particles[i];

                // Lerp
                p.current.x += (p.target.x - p.current.x) * 0.04;
                p.current.y += (p.target.y - p.current.y) * 0.04;
                p.current.z += (p.target.z - p.current.z) * 0.04;

                // Entropy in Cloud Phase
                if (phase === 0) {
                    p.current.x += Math.sin(time * 2 + i) * 0.5;
                    p.current.y += Math.cos(time * 3 + i) * 0.5;
                }

                // 3D Rotation
                let x = p.current.x;
                let y = p.current.y;
                let z = p.current.z;

                // Rotate Y
                let tx = x * cosY - z * sinY;
                let tz = z * cosY + x * sinY;
                x = tx; z = tz;

                // Rotate X
                let ty = y * cosX - z * sinX;
                let tz2 = z * cosX + y * sinX;
                y = ty; z = tz2;

                const scale = CAM_Z / (CAM_Z + z);

                if (scale > 0) {
                    // Populate sorting array directly
                    sortedParticles[validCount] = {
                        x: CX + x * scale,
                        y: CY + y * scale,
                        z: z,
                        scale: scale,
                        color: p.color,
                        size: p.size
                    };
                    validCount++;
                }
            }

            // Quick Sort (only valid items)
            // Using a simpler approach: just draw. Transparency artifacts are minimal here.
            // But if we want depth fog, sorting helps.
            const renderList = sortedParticles.slice(0, validCount).sort((a, b) => b.z - a.z);

            for(let i=0; i<renderList.length; i++) {
                const s = renderList[i];
                const alpha = Math.min(1, (s.scale * 0.7)); 
                ctx.globalAlpha = alpha;
                ctx.fillStyle = s.color;

                if (phase === 2) {
                    const size = Math.max(1, s.size * s.scale);
                    ctx.fillRect(s.x - size/2, s.y - size/2, size, size);
                } else {
                    ctx.beginPath();
                    ctx.arc(s.x, s.y, s.size * s.scale, 0, Math.PI * 2);
                    ctx.fill();
                }
            }
            ctx.globalAlpha = 1;

            // Connecting Lines (Only for structured phases)
            if (phase !== 0) {
                ctx.strokeStyle = phase === 2 ? 'rgba(34, 211, 238, 0.15)' : 'rgba(139, 92, 246, 0.1)';
                ctx.lineWidth = 0.5;

                // Optimized connection loop
                for(let i=0; i<renderList.length; i+=3) { // Skip some particles
                    const p1 = renderList[i];
                    // Only check next few sorted neighbors (approximation of proximity)
                    for(let j=1; j<3; j++) {
                        if (i+j >= renderList.length) break;
                        const p2 = renderList[i+j];

                        const dist = Math.abs(p1.x - p2.x) + Math.abs(p1.y - p2.y); // Manhattan dist for speed
                        if (dist < 40 * p1.scale) {
                            ctx.beginPath();
                            ctx.moveTo(p1.x, p1.y);
                            ctx.lineTo(p2.x, p2.y);
                            ctx.stroke();
                        }
                    }
                }
            }

            frameId = requestAnimationFrame(render);
        };

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseRef.current = {
                x: ((e.clientX - rect.left) / w) * 2 - 1,
                y: ((e.clientY - rect.top) / h) * 2 - 1
            };
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.parentElement.clientWidth;
                h = canvas.parentElement.clientHeight;
                canvas.width = w; canvas.height = h;
            }
        };
        window.addEventListener('resize', handleResize);
        window.addEventListener('mousemove', handleMouseMove);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="w-full h-full block opacity-80" />;
};

import React, { useEffect, useRef } from 'react';

export const IndustrialsHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = canvas.parentElement?.clientWidth || 800;
        let h = canvas.height = canvas.parentElement?.clientHeight || 600;
        let time = 0;
        let frameId: number;

        const CAM_Z = 600;
        const CX = w * 0.65;
        const CY = h * 0.5;
        const MODEL_SCALE = 1.4;

        interface Point { x: number, y: number, z: number }
        const parts: { points: Point[], rotationSpeed: number, color: string, type: string }[] = [];

        // CASING (Optimized)
        const casingPoints: Point[] = [];
        // Increased step from 30 to 50 for Z, 0.2 to 0.4 for angle
        for (let z = -250; z <= 250; z += 50) {
            const r = (130 + Math.sin(z * 0.008) * 15) * MODEL_SCALE;
            for (let a = 0; a < Math.PI * 2; a += 0.4) {
                casingPoints.push({ x: Math.cos(a) * r, y: Math.sin(a) * r, z: z });
            }
        }
        parts.push({ points: casingPoints, rotationSpeed: 0.001, color: 'rgba(255, 255, 255, 0.2)', type: 'casing' });

        // ROTORS
        for (let i = 0; i < 6; i++) {
            const z = -200 + i * 80;
            const pts: Point[] = [];
            const rOuter = 115 * MODEL_SCALE;
            // Reduced blade count complexity
            const bladeCount = 8 + (i%2)*4;
            for (let b = 0; b < bladeCount; b++) {
                const angle = (Math.PI * 2 / bladeCount) * b;
                pts.push({ x: Math.cos(angle) * 40 * MODEL_SCALE, y: Math.sin(angle) * 40 * MODEL_SCALE, z });
                pts.push({ x: Math.cos(angle + 0.3) * rOuter, y: Math.sin(angle + 0.3) * rOuter, z });
            }
            parts.push({ points: pts, rotationSpeed: 0.15 * (i%2===0?1:-1), color: 'rgba(245, 158, 11, 0.8)', type: 'rotor' });
        }

        const render = () => {
            time += 0.01;
            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            const camRotY = time * 0.2;
            const camRotX = Math.sin(time * 0.25) * 0.15;

            // Pre-calculate camera rotation matrix values
            const cosCY = Math.cos(camRotY), sinCY = Math.sin(camRotY);
            const cosCX = Math.cos(camRotX), sinCX = Math.sin(camRotX);

            parts.forEach(part => {
                const currentRot = time * part.rotationSpeed * 50;
                const cosR = Math.cos(currentRot);
                const sinR = Math.sin(currentRot);

                ctx.beginPath();

                // Optimized loop
                const pts = part.points;
                const len = pts.length;

                for (let i = 0; i < len; i++) {
                    const p = pts[i];
                    let x = p.x, y = p.y, z = p.z;

                    if (part.type === 'rotor') {
                        // Apply rotor spin
                        const nx = x * cosR - y * sinR;
                        const ny = x * sinR + y * cosR;
                        x = nx; y = ny;
                    }

                    // Camera Y Rotation
                    const tx = x * cosCY - z * sinCY;
                    const tz = z * cosCY + x * sinCY;
                    x = tx; z = tz;

                    // Camera X Rotation
                    const ty = y * cosCX - z * sinCX;
                    const tz2 = z * cosCX + y * sinCX;
                    y = ty; z = tz2;

                    const scale = CAM_Z / (CAM_Z + z);

                    if (scale > 0) {
                        const px = CX + x * scale;
                        const py = CY + y * scale;

                        if (part.type === 'rotor') {
                            if (i % 2 === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
                        } else {
                            // Casing: Draw dots
                            ctx.moveTo(px + 1, py); ctx.arc(px, py, 1.5 * scale, 0, Math.PI*2);
                        }
                    }
                }

                if (part.type === 'rotor') {
                    ctx.strokeStyle = part.color; ctx.stroke();
                } else {
                    ctx.fillStyle = part.color; ctx.fill();
                }
            });

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

