const ImagePlaceholder: React.FC<{ type: 'wide' | 'portrait' | 'square', label: string, caption?: string, src?: string }> = ({ type, label, caption, src }) => {
    const aspect = type === 'wide' ? 'aspect-[21/9]' : type === 'portrait' ? 'aspect-[3/4]' : 'aspect-square';

    // Intersection Observer for Reveal Effect
    const ref = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        const observer = new IntersectionObserver(([entry]) => {
            if (entry.isIntersecting) {
                setIsVisible(true);
                observer.disconnect();
            }
        }, { threshold: 0.1 });
        if (ref.current) observer.observe(ref.current);
        return () => observer.disconnect();
    }, []);

    return (
        <div ref={ref} className={`my-16 group cursor-default w-full transition-all duration-1000 transform ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
            <div className={`w-full ${aspect} bg-[#0c0c0e] border border-white/10 rounded-lg relative overflow-hidden group`}>

                {src ? (
                    <>
                        <img 
                            src={src} 
                            alt={label}
                            className="absolute inset-0 w-full h-full object-cover transition-transform duration-[1.5s] ease-out scale-100 group-hover:scale-105 brightness-90 group-hover:brightness-110"
                        />
                        {/* Subtle Vignette */}
                        <div className="absolute inset-0 bg-gradient-to-t from-[#0c0c0e]/80 via-transparent to-transparent opacity-60" />

                        {/* Bloom Glow on Hover */}
                        <div className="absolute inset-0 bg-purple-500/0 group-hover:bg-purple-500/10 transition-colors duration-700 mix-blend-overlay" />

                        {/* Shine Effect */}
                        <div className="absolute -inset-full top-0 block h-full w-1/2 -skew-x-12 bg-gradient-to-r from-transparent to-white opacity-0 group-hover:animate-shine" />
                    </>
                ) : (
                    <div className="absolute inset-0 opacity-10 transition-transform duration-[20s] ease-linear group-hover:scale-110" style={{ backgroundImage: 'linear-gradient(#ffffff 1px, transparent 1px), linear-gradient(90deg, #ffffff 1px, transparent 1px)', backgroundSize: '40px 40px' }} />
                )}

                {/* Scanline - only visible on hover */}
                <div className="absolute top-0 left-0 w-full h-1 bg-purple-400/30 blur-md animate-[scan_4s_linear_infinite] opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>

            {caption && (
                <div className="mt-4 flex gap-4 text-xs font-mono text-white/40 border-l border-purple-500/30 pl-4 group-hover:text-white/60 transition-colors">
                    <span className="text-purple-500">FIG</span>
                    <span>{caption}</span>
                </div>
            )}
        </div>
    );
};

