            for (let i = -2; i < BASE_PAIRS + 2; i++) {
                const xBase = (i * spacing + time * 0.5) % (width + spacing * 4) - spacing * 2;
                const angle = i * 0.4 + time * ROTATION_SPEED;

                const distToScan = Math.abs(xBase - scanX);
                const isScanned = distToScan < 80;
                const scanIntensity = Math.max(0, 1 - distToScan / 80);

                const y1 = cy + Math.sin(angle) * amplitude;
                const z1 = Math.cos(angle);
                const y2 = cy + Math.sin(angle + Math.PI) * amplitude;
                const z2 = Math.cos(angle + Math.PI);

                if (xBase > -50 && xBase < width + 50) {
                    ctx.lineWidth = isScanned ? 2 : 1;
                    const strokeColor = isScanned ? `rgba(255, 255, 255, ${scanIntensity * 0.8})` : `rgba(20, 184, 166, 0.1)`;
                    ctx.strokeStyle = strokeColor;
                    ctx.beginPath(); ctx.moveTo(xBase, y1); ctx.lineTo(xBase, y2); ctx.stroke();
                }

                const scale1 = 1 + z1 * 0.3;
                ctx.beginPath(); ctx.arc(xBase, y1, 4 * scale1, 0, Math.PI*2); 
                ctx.fillStyle = isScanned ? `rgba(255, 255, 255, ${scanIntensity})` : `rgba(45, 212, 191, ${0.2 + (z1+1)*0.3})`;
                ctx.fill();

                const scale2 = 1 + z2 * 0.3;
                ctx.beginPath(); ctx.arc(xBase, y2, 4 * scale2, 0, Math.PI*2);
                ctx.fill();
            }

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                width = canvas.width = canvas.parentElement.clientWidth;
                height = canvas.height = canvas.parentElement.clientHeight;
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

import React, { useEffect, useRef } from 'react';

export const ResourcesHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.parentElement?.clientWidth || 800;
        let h = canvas.parentElement?.clientHeight || 600;
        canvas.width = w;
        canvas.height = h;

        let frame = 0;
        let animationFrameId: number;

        // State for dynamic events
        const extractions: { x: number, y: number, life: number, code: string, color: string }[] = [];
        const NODE_COLORS = ['#f59e0b', '#06b6d4', '#d946ef', '#ef4444', '#10b981', '#f43f5e'];

        const render = () => {
            frame++;
            const time = frame * 0.008; 
            const scroll = frame * 2.0;

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, w, h);

            // 2. Draw "Strata" Lines (Restored High Density)
            const lines = 55; // Restored from 35
            const step = h / lines;
            const scanX = (w/2) + Math.sin(time * 0.5) * (w * 0.4);

            for (let i = 0; i < lines; i++) {
                const normI = i / lines;
                const perspectiveY = h * (0.2 + Math.pow(normI, 1.2) * 0.8);

                ctx.beginPath();

                const alpha = normI * 0.6 + 0.1;
                const hue = 160 + (1-normI) * 60; 

                // Restored Step: 3px (was 8px)
                for (let x = 0; x <= w; x += 3) {
                    const worldX = x + scroll;
                    const worldZ = i * 50; 

                    // Complex Terrain Math
                    let elevation = Math.sin(worldX * 0.002 + worldZ * 0.001) * 40;

                    // Complex ridges
                    const ridge1 = Math.pow(1 - Math.abs(Math.sin(worldX * 0.006 + time * 0.2)), 3);
                    elevation -= ridge1 * 50; 

                    // Scanner Interaction
                    const distToScan = Math.abs(x - scanX);
                    if (distToScan < 120) {
                        const scanInfluence = 1 - distToScan / 120;
                        elevation += Math.sin(x * 0.2) * 5 * scanInfluence;
                    }

                    const finalY = perspectiveY + elevation;

                    if (x === 0) ctx.moveTo(x, finalY);
                    else ctx.lineTo(x, finalY);
                }

                ctx.strokeStyle = `hsla(${hue}, 50%, 40%, ${alpha * 0.3})`;
                ctx.lineWidth = 1 + normI;

                if (scanX > -150 && scanX < w + 150) {
                    const grad = ctx.createLinearGradient(scanX - 100, 0, scanX + 100, 0);
                    grad.addColorStop(0, `hsla(${hue}, 50%, 40%, ${alpha * 0.3})`);
                    grad.addColorStop(0.5, `hsla(${hue - 40}, 90%, 80%, ${alpha})`);
                    grad.addColorStop(1, `hsla(${hue}, 50%, 40%, ${alpha * 0.3})`);
                    ctx.strokeStyle = grad;
                }

                ctx.stroke();
            }

            // 3. Draw Resources & Extraction (Restored Count)
            const dotCount = 15; // Restored from 6
            for(let j=0; j<dotCount; j++) {
                const nodeColor = NODE_COLORS[j % NODE_COLORS.length];
                const virtualX = (j * (w / dotCount) + scroll * 0.5) % (w + 200) - 100;

                if (virtualX < -50 || virtualX > w + 50) continue;

                const perspectiveY = h * (0.2 + Math.pow(0.7, 1.2) * 0.8);
                const dy = perspectiveY + Math.sin(virtualX * 0.002) * 40; // Approx Y

                const distToScan = Math.abs(virtualX - scanX);

                // Trigger Extraction
                if (distToScan < 30 && Math.random() > 0.99) { 
                    const tooClose = extractions.some(e => Math.abs(e.x - virtualX) < 40);
                    if (!tooClose) {
                        extractions.push({ 
                            x: virtualX, y: dy, life: 1.0, 
                            code: "RES-" + Math.floor(Math.random() * 99),
                            color: nodeColor
                        });
                    }
                }

                if (distToScan < 100) {
                    ctx.fillStyle = '#fff';
                    ctx.shadowColor = nodeColor;
                    ctx.shadowBlur = 10;
                    ctx.beginPath(); ctx.arc(virtualX, dy, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                }
            }

            // 4. Render Active Extractions
            for (let i = extractions.length - 1; i >= 0; i--) {
                const ex = extractions[i];
                ex.life -= 0.02;
                ex.x -= 1.0; 

                if (ex.life <= 0) {
                    extractions.splice(i, 1);
                    continue;
                }

                const beamHeight = 150 * (1 - ex.life);
                ctx.fillStyle = ex.color;
                ctx.globalAlpha = Math.sin(ex.life * Math.PI) * 0.6;
                ctx.fillRect(ex.x - 1, ex.y - beamHeight, 2, beamHeight);
                ctx.globalAlpha = 1;
            }

            animationFrameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                w = canvas.parentElement.clientWidth;
                h = canvas.parentElement.clientHeight;
                canvas.width = w;
                canvas.height = h;
            }
        };
        window.addEventListener('resize', handleResize);
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

import React, { useEffect, useRef } from 'react';

export const HeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = canvas.width;
        let height = canvas.height;
        let frameId: number;

        // --- 3D ENGINE SETTINGS ---
        const FL = 800;
        let cx = width / 2;
        let cy = height / 2;
        let mouseX = 0;
        let mouseY = 0;
        let targetRotX = 0;
        let targetRotY = 0;

        // --- ANIMATION STATE ---
        let phase = 0; 
        let phaseTimer = 0;
        let globalTime = 0;
        let loopSeed = 0; 
        let meshOpacity = 0; 

        // --- GEOMETRY ---
        const SHEET_SIZE = 150; 

        // Base structures
        const flatVerts = [
            { x: -SHEET_SIZE, y: -SHEET_SIZE * 1.4, z: 0 }, { x: 0, y: -SHEET_SIZE * 1.4, z: 0 }, { x: SHEET_SIZE, y: -SHEET_SIZE * 1.4, z: 0 },
            { x: -SHEET_SIZE, y: 0, z: 0 },                 { x: 0, y: 0, z: 0 },                 { x: SHEET_SIZE, y: 0, z: 0 },
            { x: -SHEET_SIZE, y: SHEET_SIZE * 1.4, z: 0 },  { x: 0, y: SHEET_SIZE * 1.4, z: 0 },  { x: SHEET_SIZE, y: SHEET_SIZE * 1.4, z: 0 }
        ];

        const planeVerts = [
            { x: 0, y: -SHEET_SIZE * 1.8, z: -20 },   { x: 0, y: -SHEET_SIZE * 1.8, z: -20 },   { x: 0, y: -SHEET_SIZE * 1.8, z: -20 },
            { x: -SHEET_SIZE * 1.2, y: SHEET_SIZE, z: 20 }, { x: 0, y: -SHEET_SIZE * 0.5, z: -50 }, { x: SHEET_SIZE * 1.2, y: SHEET_SIZE, z: 20 },
            { x: -20, y: SHEET_SIZE * 1.4, z: 0 },     { x: 0, y: SHEET_SIZE * 1.4, z: 0 },      { x: 20, y: SHEET_SIZE * 1.4, z: 0 }
        ];

        // Mutable working buffers
        const currentVerts = flatVerts.map(v => ({...v}));
        const worldVertsBuffer = flatVerts.map(() => ({ x: 0, y: 0, z: 0, px: 0, py: 0, scale: 0 }));

        let planePos = { x: 0, y: 0, z: 0 };
        let planeVel = { x: 0, y: 0, z: 0 };
        let planeRot = { x: 0, y: 0, z: 0 };

        // --- PARTICLES ---
        interface Particle {
            x: number; y: number; z: number;
            vx: number; vy: number; vz: number;
            life: number;
            color: string;
            type: 'data' | 'trail' | 'ember';
            active: boolean;
        }

        const MAX_PARTICLES = 200; // Restored from 100
        const particles: Particle[] = [];
        // Init pool
        for(let i=0; i<MAX_PARTICLES; i++) {
            particles.push({ x:0, y:0, z:0, vx:0, vy:0, vz:0, life:0, color:'#fff', type:'ember', active: false });
        }

        // --- HELPERS ---
        const lerp = (start: number, end: number, t: number) => start + (end - start) * t;

        const spawnParticle = (type: 'data' | 'trail' | 'ember', ox: number, oy: number, oz: number, spread: number) => {
            // Find inactive particle
            const p = particles.find(p => !p.active);
            if (!p) return;

            p.active = true;
            p.x = ox + (Math.random()-0.5) * spread;
            p.y = oy + (Math.random()-0.5) * spread;
            p.z = oz + (Math.random()-0.5) * spread;
            p.vx = (Math.random()-0.5) * (type === 'ember' ? 5 : 2);
            p.vy = (Math.random()-0.5) * (type === 'ember' ? 5 : 2);
            p.vz = type === 'trail' ? 10 : (Math.random()-0.5) * 5;
            p.life = 1.0;
            p.color = type === 'data' ? '#69B7B2' : type === 'ember' ? '#f59e0b' : '#ffffff';
            p.type = type;
        };

        // --- MAIN LOOP ---
        const render = () => {
            globalTime += 0.016;
            ctx.fillStyle = 'rgba(2, 2, 2, 0.3)';
            ctx.fillRect(0, 0, width, height);

            targetRotY += (mouseX * 0.5 - targetRotY) * 0.05;
            targetRotX += (mouseY * 0.5 - targetRotX) * 0.05;

            // Pre-calc rotation matrices
            const cosY = Math.cos(targetRotX); 
            const sinY = Math.sin(targetRotX);
            const cosX = Math.cos(targetRotY); 
            const sinX = Math.sin(targetRotY);

            // --- PHASE LOGIC ---
            if (phase === 0) { // COALESCE
                phaseTimer += 0.006;
                meshOpacity = Math.min(1, phaseTimer);
                const t = Math.min(1, phaseTimer / 2.0);
                const ease = 1 - Math.pow(1 - t, 4); 

                for(let i=0; i<9; i++) {
                    const float = Math.sin(globalTime * 2 + i) * 20 * (1-ease);
                    const noiseX = Math.sin(i * 12.3 + loopSeed) * 1200 + float;
                    const noiseY = Math.cos(i * 45.6 + loopSeed) * 800 + float;
                    const noiseZ = Math.sin(i * 78.9 + loopSeed) * 1000 - 500;

                    currentVerts[i].x = lerp(noiseX, flatVerts[i].x, ease);
                    currentVerts[i].y = lerp(noiseY, flatVerts[i].y, ease);
                    currentVerts[i].z = lerp(noiseZ, flatVerts[i].z, ease);
                }

                if (Math.random() > 0.85 && phaseTimer < 1.5) spawnParticle('data', 0, 0, 0, 800);
                if (phaseTimer > 2.5) { phase = 1; phaseTimer = 0; meshOpacity = 1; }
            }
            else if (phase === 1) { // FOLD
                phaseTimer += 0.012;
                const t = Math.min(1, phaseTimer);
                const ease = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;

                for(let i=0; i<9; i++) {
                    currentVerts[i].x = lerp(flatVerts[i].x, planeVerts[i].x, ease);
                    currentVerts[i].y = lerp(flatVerts[i].y, planeVerts[i].y, ease);
                    currentVerts[i].z = lerp(flatVerts[i].z, planeVerts[i].z, ease);
                }

                if (t > 0.8) {
                    cx = width/2 + (Math.random()-0.5)*5;
                    cy = height/2 + (Math.random()-0.5)*5;
                } else {
                    cx = width/2; cy = height/2;
                }

                if (phaseTimer > 1.2) { 
                    phase = 2; phaseTimer = 0;
                    const angle = (Math.random() - 0.5) * 2.5;
                    const lift = (Math.random() - 0.5) * 1.0;
                    planeVel = { x: Math.sin(angle) * 8, y: Math.sin(lift) * 6, z: 18 };
                }
            }
            else if (phase === 2) { // FLIGHT
                phaseTimer += 0.016;
                planeVel.z += 0.85;
                planePos.x += planeVel.x;
                planePos.y += planeVel.y;
                planePos.z += planeVel.z;

                const targetBank = planeVel.x * 0.03;
                planeRot.z += (targetBank - planeRot.z) * 0.1;
                const targetPitch = planeVel.y * 0.03;
                planeRot.x += (targetPitch - planeRot.x) * 0.1;
                planeRot.y += planeVel.x * 0.002;

                if (planePos.z > 2000) meshOpacity = Math.max(0, 1 - ((planePos.z - 2000) / 1500));

                if(Math.random() > 0.5) spawnParticle('ember', planePos.x, planePos.y, planePos.z, 10);
                if(Math.random() > 0.8) spawnParticle('trail', planePos.x, planePos.y, planePos.z, 20);

                if (planePos.z > 3500) { phase = 3; phaseTimer = 0; }
            }
            else if (phase === 3) { // RESET
                planePos = { x: 0, y: 0, z: 0 };
                planeVel = { x: 0, y: 0, z: 0 };
                planeRot = { x: 0, y: 0, z: 0 };
                loopSeed += 13.7;
                meshOpacity = 0;
                phase = 0;
            }

            // --- TRANSFORM & PROJECT ---
            for(let i=0; i<9; i++) {
                const v = currentVerts[i];
                let x = v.x + planePos.x;
                let y = v.y + planePos.y;
                let z = v.z + planePos.z;

                if (phase === 2) {
                    // Local Rotation
                    let lx = v.x, ly = v.y, lz = v.z;
                    // Y-rot (Simplified order for speed)
                    let tx = lx * Math.cos(planeRot.y) - lz * Math.sin(planeRot.y);
                    let tz = lz * Math.cos(planeRot.y) + lx * Math.sin(planeRot.y);
                    lx = tx; lz = tz;
                    // Z-rot
                    let tx2 = lx * Math.cos(planeRot.z) - ly * Math.sin(planeRot.z);
                    let ty2 = ly * Math.cos(planeRot.z) + lx * Math.sin(planeRot.z);
                    lx = tx2; ly = ty2;
                    // X-rot
                    let ty3 = ly * Math.cos(planeRot.x) - lz * Math.sin(planeRot.x);
                    let tz3 = lz * Math.cos(planeRot.x) + ly * Math.sin(planeRot.x);
                    ly = ty3; lz = tz3;

                    x = lx + planePos.x;
                    y = ly + planePos.y;
                    z = lz + planePos.z;
                }

                // Global Rotation
                let y1 = y * cosY - z * sinY;
                let z1 = z * cosY + y * sinY;
                let x1 = x * cosX - z1 * sinX;
                let z2 = z1 * cosX + x * sinX;

                const scale = FL / (FL + z2);
                worldVertsBuffer[i].x = x1;
                worldVertsBuffer[i].y = y1;
                worldVertsBuffer[i].z = z2;
                worldVertsBuffer[i].px = cx + x1 * scale;
                worldVertsBuffer[i].py = cy + y1 * scale;
                worldVertsBuffer[i].scale = scale;
            }

            // --- DRAW MESH ---
            if (meshOpacity > 0.01) {
                const color = phase === 2 ? '#69B7B2' : '#e5e5e5';
                const strokeColor = `rgba(255,255,255,${0.1 * meshOpacity})`;
                const accentFill = phase === 2 ? `rgba(105,183,178,0.2)` : 'rgba(255,255,255,0.1)';

                ctx.lineWidth = 1;
                ctx.strokeStyle = strokeColor;

                // Helper to draw tri
                const dt = (i1: number, i2: number, i3: number, fill: string) => {
                    const p1 = worldVertsBuffer[i1];
                    const p2 = worldVertsBuffer[i2];
                    const p3 = worldVertsBuffer[i3];
                    if (p1.z < -FL+10 || p2.z < -FL+10 || p3.z < -FL+10) return;

                    ctx.fillStyle = fill;
                    ctx.beginPath();
                    ctx.moveTo(p1.px, p1.py);
                    ctx.lineTo(p2.px, p2.py);
                    ctx.lineTo(p3.px, p3.py);
                    ctx.closePath();
                    ctx.fill();
                    ctx.stroke();
                };

                ctx.globalAlpha = meshOpacity;
                dt(0, 1, 3, `rgba(255,255,255,0.05)`);
                dt(1, 4, 3, accentFill);
                dt(1, 2, 5, `rgba(255,255,255,0.05)`);
                dt(1, 4, 5, accentFill);
                dt(3, 4, 6, `rgba(255,255,255,0.05)`);
                dt(4, 5, 8, `rgba(255,255,255,0.05)`);
                dt(4, 7, 6, accentFill);
                dt(4, 7, 8, accentFill);

                // Leading edges
                const p1 = worldVertsBuffer[1]; const p4 = worldVertsBuffer[4]; const p7 = worldVertsBuffer[7];
                if(p1.z > -FL) {
                    ctx.strokeStyle = phase === 1 ? '#f59e0b' : color;
                    ctx.lineWidth = 2;
                    ctx.beginPath(); ctx.moveTo(p1.px, p1.py); ctx.lineTo(p4.px, p4.py); ctx.lineTo(p7.px, p7.py); ctx.stroke();
                }
                ctx.globalAlpha = 1;
            }

            // --- DRAW PARTICLES ---
            for(let i=0; i<MAX_PARTICLES; i++) {
                const p = particles[i];
                if (!p.active) continue;

                p.x += p.vx; p.y += p.vy; p.z += p.vz;
                p.life -= 0.02;

                if (p.life <= 0 || p.z > 2000) {
                    p.active = false;
                    continue;
                }

                // Rotate Particle
                let y1 = p.y * cosY - p.z * sinY;
                let z1 = p.z * cosY + p.y * sinY;
                let x1 = p.x * cosX - z1 * sinX;
                let z2 = z1 * cosX + p.x * sinX;

                const scale = FL / (FL + z2);
                if (scale > 0) {
                    const px = cx + x1 * scale;
                    const py = cy + y1 * scale;

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life * (phase === 2 ? meshOpacity : 1);

                    if (p.type === 'data') {
                        ctx.fillText(Math.random() > 0.5 ? "1" : "0", px, py);
                    } else {
                        const size = (p.type === 'trail' ? 3 : 6) * scale;
                        ctx.beginPath(); ctx.arc(px, py, size, 0, Math.PI*2); ctx.fill();
                    }
                }
            }
            ctx.globalAlpha = 1;

            frameId = requestAnimationFrame(render);
        };

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseX = ((e.clientX - rect.left) / width) * 2 - 1;
            mouseY = ((e.clientY - rect.top) / height) * 2 - 1;
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                canvas.width = canvas.parentElement.clientWidth;
                canvas.height = canvas.parentElement.clientHeight;
                width = canvas.width;
                height = canvas.height;
                cx = width / 2;
                cy = height / 2;
            }
        };

        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />;
};

import React, { useEffect, useRef } from 'react';

export const HeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = canvas.width;
        let height = canvas.height;
        let frameId: number;

        // --- 3D ENGINE ---
        const FL = 800;
        let cx = width / 2;
        let cy = height / 2;
        let mouseX = 0;
        let mouseY = 0;
        let targetRotX = 0;
        let targetRotY = 0;

        // Vertices for a simple paper plane
        const S = 100;
        const vertices = [
            { x: 0, y: -S * 0.5, z: 50 },   // Nose
            { x: -S, y: S, z: 0 },          // Left Wing
            { x: S, y: S, z: 0 },           // Right Wing
            { x: 0, y: S * 0.8, z: -20 },   // Tail bottom
        ];

        // Particles
        const particles: { x: number, y: number, z: number, speed: number }[] = [];
        for(let i=0; i<60; i++) {
            particles.push({ 
                x: (Math.random()-0.5)*width*2, 
                y: (Math.random()-0.5)*height*2, 
                z: Math.random() * 2000,
                speed: 10 + Math.random() * 20
            });
        }

        const render = () => {
            // Clear
            ctx.fillStyle = 'rgba(2, 2, 2, 0.2)'; // Trails
            ctx.fillRect(0, 0, width, height);

            // Mouse interaction
            targetRotY += (mouseX * 0.3 - targetRotY) * 0.05;
            targetRotX += (mouseY * 0.3 - targetRotX) * 0.05;

            // Draw Particles (Starfield flow)
            ctx.fillStyle = '#ffffff';
            particles.forEach(p => {
                p.z -= p.speed;
                if (p.z < -FL) p.z += 2000;

                // Rotation
                let x = p.x; let y = p.y; let z = p.z;
                let x1 = x * Math.cos(targetRotY) - z * Math.sin(targetRotY);
                let z1 = z * Math.cos(targetRotY) + x * Math.sin(targetRotY);
                let y1 = y * Math.cos(targetRotX) - z1 * Math.sin(targetRotX);
                let z2 = z1 * Math.cos(targetRotX) + y * Math.sin(targetRotX);

                const scale = FL / (FL + z2);
                if (scale > 0) {
                    const alpha = Math.min(1, scale * 0.5);
                    ctx.globalAlpha = alpha;
                    ctx.beginPath(); ctx.arc(cx + x1 * scale, cy + y1 * scale, 1.5 * scale, 0, Math.PI*2); ctx.fill();
                }
            });

            // Draw Plane Mesh
            ctx.globalAlpha = 1;
            ctx.strokeStyle = '#69B7B2';
            ctx.lineWidth = 2;
            ctx.beginPath();

            // Transform Plane Verts
            const pV = vertices.map(v => {
                // Local Rotation (Bank)
                let x = v.x; let y = v.y; let z = v.z;
                const bank = -targetRotY * 0.5;
                const pitch = targetRotX * 0.5;

                // Rotate Z (Bank)
                let tx = x * Math.cos(bank) - y * Math.sin(bank);
                let ty = y * Math.cos(bank) + x * Math.sin(bank);
                x = tx; y = ty;

                // Rotate X (Pitch)
                let ty2 = y * Math.cos(pitch) - z * Math.sin(pitch);
                let tz2 = z * Math.cos(pitch) + y * Math.sin(pitch);
                y = ty2; z = tz2;

                // Project
                const scale = FL / (FL + z + 400); // Offset z to keep it visible
                return { x: cx + x * scale, y: cy + y * scale };
            });

            // Draw Lines
            ctx.moveTo(pV[0].x, pV[0].y); ctx.lineTo(pV[1].x, pV[1].y); // Nose to Left
            ctx.lineTo(pV[3].x, pV[3].y); // Left to Tail
            ctx.lineTo(pV[2].x, pV[2].y); // Tail to Right
            ctx.lineTo(pV[0].x, pV[0].y); // Right to Nose
            ctx.moveTo(pV[0].x, pV[0].y); ctx.lineTo(pV[3].x, pV[3].y); // Spine

            ctx.stroke();

            // Fill
            ctx.fillStyle = 'rgba(105, 183, 178, 0.1)';
            ctx.fill();

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                canvas.width = canvas.parentElement.clientWidth;
                canvas.height = canvas.parentElement.clientHeight;
                width = canvas.width;
                height = canvas.height;
                cx = width / 2;
                cy = height / 2;
            }
        };
        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            mouseX = ((e.clientX - rect.left) / width) * 2 - 1;
            mouseY = ((e.clientY - rect.top) / height) * 2 - 1;
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('mousemove', handleMouseMove);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-80" />;
};
